import type {RequestContext} from './context.ts';
export function createContext(value: string, userId: string): RequestContext {return {traceId:value,userId};}
export function forkContext(context: RequestContext, suffix: string): RequestContext {return {...context, traceId: context.traceId+'/'+suffix};}

import type {RequestContext} from './context.ts';
import {auditLabel} from './job-types.ts';
import type {Job} from './job-types.ts';
export function describeJob(job: Job, context: RequestContext) {return {requestId:job.requestId,trace:context.traceId,audit:auditLabel(job.requestId),name:job.name};}

import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {handle} from '../src/app.ts';
import {createContext, forkContext} from '../src/context-factory.ts';
import {describeJob} from '../src/jobs.ts';
import {headers} from '../src/middleware.ts';
import {logFields} from '../src/logging.ts';
import {response} from '../src/response.ts';
import {traceSummary} from '../src/plugins/index.ts';
import {record0, audit0} from '../src/catalog/record0.ts';

describe('RequestContext rename and end-to-end propagation', () => {
  test('end-to-end propagation through handle', () => {
    const job = {requestId: 'job-xyz-456', name: 'process-orders'};
    const result = handle('trace-abc-123', 'user-test-789', job);

    // Context field rename and absence of requestId
    assert.equal(result.context.traceId, 'trace-abc-123');
    assert.equal(result.context.userId, 'user-test-789');
    assert.equal('requestId' in result.context, false, 'RequestContext must not have requestId property');
    assert.equal(result.context.requestId, undefined);

    // Middleware headers wire key
    assert.equal(result.headers['x-request-id'], 'trace-abc-123');

    // Logging output keys: requestId preserved as wire key with traceId value
    assert.equal(result.logs.requestId, 'trace-abc-123');
    assert.equal(result.logs.userId, 'user-test-789');

    // Response wire key: requestId preserved as wire key with traceId value
    assert.equal(result.body.requestId, 'trace-abc-123');

    // Worker payload: trace propagated with forkContext suffix
    assert.equal(result.body.payload.trace, 'trace-abc-123/worker');

    // Context non-mutation: original context is not altered by forkContext
    assert.equal(result.context.traceId, 'trace-abc-123');
  });

  test('unrelated Job identifier and audit label remain unchanged', () => {
    const job = {requestId: 'job-unique-id-999', name: 'batch-indexer'};
    const result = handle('trace-live-42', 'operator-1', job);

    // Job requestId is preserved in payload output
    assert.equal(result.body.payload.requestId, 'job-unique-id-999');
    assert.equal(result.body.payload.name, 'batch-indexer');

    // Audit string is derived from job.requestId
    assert.equal(result.body.payload.audit, 'job:job-unique-id-999');

    // Direct check on describeJob
    const ctx = createContext('trace-test', 'user-test');
    const jobDescription = describeJob(job, ctx);
    assert.equal(jobDescription.requestId, 'job-unique-id-999');
    assert.equal(jobDescription.trace, 'trace-test');
    assert.equal(jobDescription.audit, 'job:job-unique-id-999');
    assert.equal(jobDescription.name, 'batch-indexer');
  });

  test('context factory construction and non-mutating forkContext', () => {
    const ctx = createContext('trace-001', 'user-alice');
    assert.equal(ctx.traceId, 'trace-001');
    assert.equal(ctx.userId, 'user-alice');
    assert.equal('requestId' in ctx, false);

    const forked = forkContext(ctx, 'subtask');
    assert.equal(forked.traceId, 'trace-001/subtask');
    assert.equal(forked.userId, 'user-alice');
    assert.equal('requestId' in forked, false);

    // Verify non-mutation of original context
    assert.equal(ctx.traceId, 'trace-001');

    const chainedFork = forkContext(forked, 'nested');
    assert.equal(chainedFork.traceId, 'trace-001/subtask/nested');
    assert.equal(forked.traceId, 'trace-001/subtask');
  });

  test('traceSummary and plugin propagation', () => {
    const ctx = createContext('trace-plugin-test', 'user-bob');
    const summary = traceSummary(ctx);

    assert.equal(summary.length, 8);
    for (let i = 0; i < 8; i++) {
      assert.deepEqual(summary[i], {
        requestId: 'trace-plugin-test',
        tag: `plugin${i}`,
        user: 'user-bob'
      });
    }
  });

  test('isolated catalog RequestContext remains independent', () => {
    const catalogCtx = {requestId: 'cat-req-123', category: 'books'};
    const rec = record0(catalogCtx);
    assert.equal(rec.requestId, 'cat-req-123');
    assert.equal(rec.category, 'books');
    assert.equal(rec.label, 'record0:cat-req-123');
    assert.equal(audit0('cat-req-123'), 'audit0:cat-req-123');
  });
});

